package com.procurement.purchaseorder.entity;import com.procurement.employee.entity.Employee;import jakarta.persistence.*;import lombok.*;import java.time.*;@Entity@Table(name="purchase_order_history")@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builder public class PurchaseOrderHistory{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="purchase_order_history_id")private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="purchase_order_id",nullable=false)private PurchaseOrder purchaseOrder;@Column(nullable=false,length=50)private String action;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="performed_by_id")private Employee performedBy;@Enumerated(EnumType.STRING)@Column(name="old_status",length=25)private PurchaseOrderStatus oldStatus;@Enumerated(EnumType.STRING)@Column(name="new_status",length=25)private PurchaseOrderStatus newStatus;@Column(length=500)private String remarks;@Column(name="performed_at",nullable=false)private LocalDateTime performedAt;@PrePersist void pre(){if(performedAt==null)performedAt=LocalDateTime.now();}}
